import{_ as t,o as d,c as o,ag as r}from"./chunks/framework.DO6ntPSX.js";const u=JSON.parse('{"title":"Supported File Types","description":"","frontmatter":{},"headers":[],"relativePath":"reference/supported-files.md","filePath":"reference/supported-files.md","lastUpdated":1785115728000}'),a={name:"reference/supported-files.md"};function c(i,e,n,s,l,p){return d(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="supported-file-types" tabindex="-1">Supported File Types <a class="header-anchor" href="#supported-file-types" aria-label="Permalink to &quot;Supported File Types&quot;">​</a></h1><p>Mneme can index and retrieve from the following file types:</p><table tabindex="0"><thead><tr><th>Type</th><th>Extensions</th></tr></thead><tbody><tr><td>PDF</td><td><code>.pdf</code></td></tr><tr><td>Word</td><td><code>.docx</code></td></tr><tr><td>Text and Markdown</td><td><code>.txt</code>, <code>.md</code>, <code>.markdown</code>, <code>.log</code></td></tr><tr><td>Web and data</td><td><code>.html</code>, <code>.htm</code>, <code>.json</code>, <code>.csv</code>, <code>.xml</code>, <code>.yaml</code>, <code>.yml</code></td></tr><tr><td>Configuration</td><td><code>.toml</code>, <code>.cfg</code>, <code>.ini</code>, <code>.conf</code></td></tr><tr><td>Source code</td><td><code>.py</code>, <code>.js</code>, <code>.ts</code>, <code>.css</code>, <code>.sql</code>, <code>.sh</code>, <code>.bat</code></td></tr></tbody></table><h2 id="pdf-handling" tabindex="-1">PDF Handling <a class="header-anchor" href="#pdf-handling" aria-label="Permalink to &quot;PDF Handling&quot;">​</a></h2><p>Mneme uses <strong>PyMuPDF</strong> (<code>fitz</code>) as the primary PDF parser, with <strong>pdfplumber</strong> as a fallback. This dual-strategy ensures robust text extraction across different PDF generation methods.</p><ul><li>Word spacing is preserved to prevent concatenation issues (e.g., <code>UniversityofPennsylvania</code>)</li><li>The first 5 lines of each PDF are used as an &quot;anchor chunk&quot; to boost retrieval relevance</li><li>Maximum page count is enforced via <code>MNEME_MAX_PDF_PAGES</code></li></ul><h2 id="security-note" tabindex="-1">Security Note <a class="header-anchor" href="#security-note" aria-label="Permalink to &quot;Security Note&quot;">​</a></h2><p>The following are <strong>explicitly rejected</strong> from indexing:</p><ul><li><code>.env</code> files (to prevent API key exposure)</li><li>Paths containing <code>..</code> (directory traversal protection)</li></ul><h2 id="document-limits" tabindex="-1">Document Limits <a class="header-anchor" href="#document-limits" aria-label="Permalink to &quot;Document Limits&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Limit</th><th>Default</th><th>Control Variable</th></tr></thead><tbody><tr><td>Max file size</td><td>50 MiB</td><td><code>MNEME_MAX_DOCUMENT_BYTES</code></td></tr><tr><td>Max PDF pages</td><td>2000</td><td><code>MNEME_MAX_PDF_PAGES</code></td></tr><tr><td>Allowed root</td><td>Optional</td><td><code>MNEME_DOCUMENT_ROOT</code></td></tr></tbody></table><p>Files exceeding these limits are skipped during indexing with a clear log message.</p>',12)])])}const f=t(a,[["render",c]]);export{u as __pageData,f as default};
